// supfix: the column types of pg_catalog and information_schema relations as PostgreSQL 16
// announces them (name 19, "char" 18, oid 26, int2 21, int4 23, real 700, xid 28, varchar 1043,
// pg_node_tree 194, int2vector 22, oidvector 30). Generated by comparing "select * from <rel>" under
// \gdesc against PostgreSQL 16 (docs/14 Appendix E item 13); the values are unchanged (Kind stays).

const (
	tyChar       = 18
	tyOid        = 26
	tyXid        = 28
	tyNodeTree   = 194
	tyInt2Vector = 22
	tyOidVector  = 30
)

