var catTypeCode = map[string]pgTy{
	"n": {oid: tyName, mod: -1}, "c": {oid: tyChar, mod: -1}, "o": {oid: tyOid, mod: -1},
	"s": {oid: tyInt2, mod: -1}, "i": {oid: tyInt4, mod: -1}, "f": {oid: tyFloat4, mod: -1},
	"x": {oid: tyXid, mod: -1}, "v": {oid: tyVarchar, mod: -1}, "v3": {oid: tyVarchar, mod: 7},
	"N": {oid: tyNodeTree, mod: -1}, "V": {oid: tyInt2Vector, mod: -1}, "W": {oid: tyOidVector, mod: -1},
}

// supfixFamily is the Kind whose values the extra catalog OIDs describe.
func supfixFamily(oid uint32) Kind {
	switch oid {
	case tyOid, tyXid:
		return KInt
	case tyChar, tyNodeTree, tyInt2Vector, tyOidVector:
		return KText
	}
	return KNull
}

// supfixBinary is the binary form of the extra catalog OIDs.
func supfixBinary(oid uint32, d Datum) ([]byte, bool) {
	switch oid {
	case tyOid, tyXid:
		if d.K == KInt {
			return binary.BigEndian.AppendUint32(nil, uint32(d.I)), true
		}
	case tyChar:
		if d.K == KText {
			if len(d.S) == 0 {
				return []byte{0}, true
			}
			return []byte{d.S[0]}, true
		}
	}
	return nil, false
}

func init() {
	for rel, spec := range catColTypes {
		cr := catalogTables[rel]
		if cr == nil {
			continue
		}
		for _, f := range strings.Fields(spec) {
			col, code, _ := strings.Cut(f, "=")
			for i := range cr.cols {
				if cr.cols[i].name == col {
					cr.cols[i].ty = catTypeCode[code]
				}
			}
		}
	}
}
